package com.shanjay.mart.controller;
import com.shanjay.mart.dao.*;import com.shanjay.mart.model.*;import com.shanjay.mart.service.ShopService;import javax.servlet.*;import javax.servlet.http.*;import java.io.IOException;
public class CartServlet extends HttpServlet{private ShopService shop;public void init(){var ds=(javax.sql.DataSource)getServletContext().getAttribute("ds");shop=new ShopService(new ProductDAO(ds),new CartDAO(ds),new OrderDAO(ds));}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{User u=(User)r.getSession().getAttribute("user");String action=r.getParameter("action");long pid=Long.parseLong(r.getParameter("productId"));if("remove".equals(action))shop.removeCart(u.id,pid);else shop.addCart(u.id,pid,Integer.parseInt(r.getParameter("quantity")));s.sendRedirect(r.getContextPath()+"/cart");}catch(Exception e){s.sendRedirect(r.getContextPath()+"/shop?error=1");}}protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");var items=shop.getCart(u.id);r.setAttribute("items",items);r.setAttribute("total",shop.total(items));r.getRequestDispatcher("/WEB-INF/views/cart.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}}
